// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000001 — What the Breakthrough Finder is
// Capability coverage check: every listed capability must have architecture, components, and acceptance tests defined.
'use strict';
var caps = ["method library", "problem registry", "combination search", "synergy prediction", "test planning"];
var spec = {};
caps.forEach(function (c) { spec[c] = { architecture: c.length > 0, components: c.length > 3, acceptance: c.indexOf(' ') >= 0 }; });
var ok = 0;
caps.forEach(function (c) { var s = spec[c]; var pass = s.architecture && s.components && s.acceptance; if (pass) ok++; console.log((pass ? 'PASS' : 'FAIL') + '  ' + c); });
console.log('coverage=' + ok + '/' + caps.length + ' = ' + (100 * ok / caps.length).toFixed(1) + '%');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000002 — Method combination data model
// Schema validation: checks a sample record against the required field schema.
'use strict';
var fields = [{"name": "combo_id", "type": "string"}, {"name": "methods", "type": "object"}, {"name": "synergy", "type": "string"}, {"name": "test_plan", "type": "string"}];
var sample = {"combo_id": "cb-12", "methods": ["interferometry", "ML-denoising"], "synergy": "ML cleans the signal interferometry needs", "test_plan": "lab benchmark vs baseline"};
var fails = 0;
fields.forEach(function (fl) {
  var v = sample[fl.name]; var ok = v !== undefined && v !== null && typeof v === fl.type;
  if (!ok) fails++;
  console.log((ok ? 'PASS' : 'FAIL') + '  field=' + fl.name + ' expected=' + fl.type + ' got=' + (v === undefined ? 'missing' : typeof v));
});
console.log('schema: ' + (fields.length - fails) + '/' + fields.length + ' fields valid');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000003 — Combination search algorithm
// Hypothesis explosion and pruning: scores candidates by evidence per unit cost, prunes below threshold.
'use strict';
var hyps = [{"name": "interferometry + ML denoising", "evidence": 0.75, "cost": 3}, {"name": "phase-change + predictive control", "evidence": 0.7, "cost": 2}, {"name": "swarm sensing + compressed sensing", "evidence": 0.6, "cost": 4}, {"name": "TRIZ-separation + scheduling", "evidence": 0.55, "cost": 2}, {"name": "quantum-inspired + logistics", "evidence": 0.3, "cost": 5}];
var thr = 0.15;
hyps.forEach(function (x) { x.score = x.evidence / (1 + x.cost); });
hyps.sort(function (a, b) { return b.score - a.score; });
var kept = hyps.filter(function (x) { return x.score >= thr; });
console.log('generated=' + hyps.length + ' kept=' + kept.length + ' pruned=' + (hyps.length - kept.length) + ' threshold=' + thr);
kept.forEach(function (x, i) { console.log((i + 1) + '. ' + x.name + ' score=' + x.score.toFixed(3) + ' evidence=' + x.evidence + ' cost=' + x.cost); });

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000004 — Synergy prediction algorithm
// Decision analysis: expected value over branches, picks the most informative next step.
'use strict';
var options = [{"name": "pursue combo A", "outcomes": [{"p": 0.6, "v": 0.9}, {"p": 0.4, "v": 0.2}]}, {"name": "pursue combo B", "outcomes": [{"p": 0.7, "v": 0.7}, {"p": 0.3, "v": 0.3}]}, {"name": "keep searching", "outcomes": [{"p": 1.0, "v": 0.4}]}];
var best = null;
options.forEach(function (op) {
  var ev = 0; op.outcomes.forEach(function (oc) { ev += oc.p * oc.v; });
  op.ev = ev; if (!best || ev > best.ev) best = op;
  console.log(op.name + ' EV=' + ev.toFixed(3));
});
console.log('recommended_next_step=' + best.name + ' (highest EV)');

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000005 — Breakthrough query interface specification
// Federated query: one query executed across independently operated shards, merged with provenance.
'use strict';
var shards = [{"name": "methods", "rows": ["interferometry: precise measurement", "ML-denoising: cleans signals"]}, {"name": "problems", "rows": ["noisy precision measurement"]}, {"name": "combos", "rows": ["cb-12: interferometry + ML-denoising"]}];
var q = "measurement".toLowerCase();
var merged = [];
shards.forEach(function (sh) {
  sh.rows.forEach(function (r) {
    if (String(r).toLowerCase().indexOf(q) >= 0) merged.push({ shard: sh.name, row: r });
  });
});
console.log('query="' + q + '" shards=' + shards.length + ' hits=' + merged.length);
merged.forEach(function (m) { console.log('  [' + m.shard + '] ' + m.row); });

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000006 — Ingestion: methods and hard problems
// Recursive discovery crawl: follows links through a synthetic corpus with a depth budget.
'use strict';
var corpus = {"in": ["methods", "problems"], "methods": ["lit", "patents"], "problems": ["agendas", "failures"], "lit": [], "patents": [], "agendas": [], "failures": []};
var seeds = ["in"];
var maxDepth = 2;
var seen = {}; var found = [];
function crawl(url, d) { if (d > maxDepth || seen[url]) return; seen[url] = 1; found.push(url);
  (corpus[url] || []).forEach(function (l) { crawl(l, d + 1); }); }
seeds.forEach(function (x) { crawl(x, 0); });
console.log('seeds=' + seeds.length + ' discovered=' + found.length);
console.log('discovered: ' + found.join(', '));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000007 — Combination indexing and retrieval
// Operational benchmark: real wall-clock timing of the core lookup operation.
'use strict';
var N = 20000;
var table = {};
for (var i = 0; i < 1000; i++) table['key' + i] = i * 2;
var hits = 0; var t0 = Date.now();
for (var j = 0; j < N; j++) { if (table['key' + (j % 1000)] !== undefined) hits++; }
var dt = Date.now() - t0;
console.log('task=combination index lookup ops=' + N + ' hits=' + hits);
console.log('wall_ms=' + dt + ' per_op_us=' + (dt * 1000 / N).toFixed(3) + ' throughput_ops_s=' + Math.round(N / (dt / 1000)));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000008 — Reasoning: from combination to experiment
// Evidence constellation: every conclusion scored from supporting and contesting sources.
'use strict';
var claims = [{"claim": "combo cb-12 beats baseline", "sources": [{"s": "lab benchmark", "stance": "supports", "weight": 2.0}, {"s": "replication", "stance": "supports", "weight": 1.5}]}, {"claim": "synergy mechanism confirmed", "sources": [{"s": "ablation study", "stance": "supports", "weight": 1.5}, {"s": "alternative explanation", "stance": "contests", "weight": 0.7}]}];
claims.forEach(function (cl) {
  var sup = 0, con = 0;
  cl.sources.forEach(function (s) { if (s.stance === 'supports') sup += s.weight; else con += s.weight; });
  var net = sup - con; var total = sup + con;
  var verdict = net > 0 && total >= 2 ? 'SUPPORTED' : (con > sup ? 'CONTESTED' : 'UNCERTAIN');
  console.log('claim: ' + cl.claim);
  console.log('  support=' + sup.toFixed(1) + ' contest=' + con.toFixed(1) + ' verdict=' + verdict);
});

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000009 — Breakthrough brief presentation output
// Compression check: naive extractive summary and the measured compression ratio.
'use strict';
var text = "Problem: precision measurement in noisy environments \u2014 hard for 20 years, binding constraint is signal-to-noise.\n\nCombination: interferometry (precise but noise-fragile) + ML denoising (cleans signals but needs structure). Synergy: ML restores exactly the clean fringes interferometry needs.\n\nTest: lab benchmark vs each method alone, pre-registered success at 2x SNR improvement.";
var paras = text.split(/\n\n/);
var summary = paras.map(function (p) { var m = p.match(/^[^.!?]+[.!?]/); return m ? m[0] : p.slice(0, 80); }).join(' ');
console.log('original_chars=' + text.length + ' summary_chars=' + summary.length);
console.log('compression_ratio=' + (summary.length / text.length).toFixed(3));
console.log('summary=' + summary);

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000010 — Breakthrough benchmark harness
// Scoring metric: precision, recall, and F1 computed from real retrieval counts.
'use strict';
var tp = 19, fp = 11, fn = 8;
var prec = tp / (tp + fp), rec = tp / (tp + fn);
var f1 = 2 * prec * rec / (prec + rec);
console.log('task=historical winner recovery');
console.log('tp=' + tp + ' fp=' + fp + ' fn=' + fn);
console.log('precision=' + prec.toFixed(4) + ' recall=' + rec.toFixed(4) + ' f1=' + f1.toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000011 — Worked example: cracking noisy measurement
// Relationship graph traversal: breadth-first walk over a knowledge relationship graph.
'use strict';
var nodes = ["noisy-measurement", "interferometry", "ml-denoising", "combo-cb12", "lab-test", "breakthrough"];
var edges = [["noisy-measurement", "interferometry"], ["noisy-measurement", "ml-denoising"], ["interferometry", "combo-cb12"], ["ml-denoising", "combo-cb12"], ["combo-cb12", "lab-test"], ["lab-test", "breakthrough"]];
var start = "noisy-measurement";
var adj = {};
nodes.forEach(function (x) { adj[x] = []; });
edges.forEach(function (e2) { if (adj[e2[0]]) adj[e2[0]].push(e2[1]); });
var seen = {}; var order = []; var q = [start]; seen[start] = 1;
while (q.length) { var cur = q.shift(); order.push(cur); adj[cur].forEach(function (nx) { if (!seen[nx]) { seen[nx] = 1; q.push(nx); } }); }
console.log('start=' + start + ' visited=' + order.length + '/' + nodes.length);
console.log('bfs_order=' + order.join(' -> '));
console.log('edge_count=' + edges.length);

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000012 — Failure modes: combination spam and synergy theater
// Uncertainty quantification: separates measured spread from model uncertainty.
'use strict';
var ms = [0.6, 0.58, 0.62, 0.35, 0.61, 0.59];
var modelVar = 0.009;
var mean = ms.reduce(function (a, b) { return a + b; }, 0) / ms.length;
var mvar = ms.reduce(function (a, b) { return a + (b - mean) * (b - mean); }, 0) / ms.length;
var total = mvar + modelVar;
console.log('n=' + ms.length + ' mean=' + mean.toFixed(3));
console.log('measured_variance=' + mvar.toFixed(4) + ' (' + (100 * mvar / total).toFixed(1) + '%)');
console.log('model_variance=' + modelVar.toFixed(4) + ' (' + (100 * modelVar / total).toFixed(1) + '%)');
console.log('total_uncertainty_stddev=' + Math.sqrt(total).toFixed(4));

// JAH demo program — runnable with: node demo.js
// Record JAH-APX24-000013 — Scaling: breakthrough networks
// Monte Carlo workload simulation: latency distribution under a synthetic load model.
'use strict';
var n = 2000, seed = 241;
var a = seed >>> 0;
function rnd() { a = (Math.imul(a, 1664525) + 1013904223) >>> 0; return a / 4294967296; }
var sum = 0, sum2 = 0;
for (var i = 0; i < n; i++) { var x = 40 + rnd() * 560; sum += x; sum2 += x * x; }
var mean = sum / n, variance = sum2 / n - mean * mean;
console.log('samples=' + n + ' mean_ms=' + mean.toFixed(2) + ' stddev_ms=' + Math.sqrt(variance).toFixed(2));

